const decisions = JSON.parse(items[0].json.output);
const mainJson = $('Data_Fetcher').first().json;

// Map decisions by type for safe lookup
const decisionMap = {};
decisions.forEach(d => {
  decisionMap[d.type.toLowerCase()] = d.decision;
});

// Apply classifications back onto the main json actuators
const updatedActuators = mainJson.actuators.map(a => {
  const decision = decisionMap[a.type.toLowerCase()];

  if (!decision) return a; // no decision found, leave untouched

  if (a.control_mode === 'auto') {
    return {
      ...a,
      classification: decision === 'TURN ON' ? 'TURN-ON' : 'KEEP-OFF'
    };
  }

  if (a.control_mode === 'semi-auto') {
    const status   = a.status.toLowerCase();
    const deciding = decision.toLowerCase();

    let classification;
    if      (status === 'off' && deciding === 'turn on')  classification = 'TURN-ON';
    else if (status === 'on'  && deciding === 'turn off') classification = 'TURN-OFF';
    else if (status === 'off' && deciding === 'turn off') classification = 'KEEP-OFF';
    else if (status === 'on'  && deciding === 'turn on')  classification = 'KEEP-ON';
    else classification = a.classification; // fallback

    return { ...a, classification };
  }

  return a; // fallback for unknown control mode
});

return [{ json: { ...mainJson, actuators: updatedActuators } }];

const input = items[0].json;

// ─── Helpers ──────────────────────────────────────────────────────────────────

function shouldIncludeActuator(actuator) {
  if (actuator.control_mode === 'auto')      return actuator.skipped === false;
  if (actuator.control_mode === 'semi-auto') return actuator.classification !== 'FUTURE-RE-EVALUATING';
  return false;
}

// ─── Filter actuators first ───────────────────────────────────────────────────

const filteredActuators = (input.actuators ?? [])
  .filter(shouldIncludeActuator)
  .map(a => ({
    type:           a.type,
    status:         a.status,
    control_mode:   a.control_mode,
    classification: a.classification
  }));

// ─── Stop if no actuators passed the filter ───────────────────────────────────

if (filteredActuators.length === 0) {
  return null;
}

// ─── Filter & reshape ─────────────────────────────────────────────────────────

const output = {
  time: input.meta?.triggered_at ?? null,
  farm: input.farm ?? null,
  sensors: (input.sensors ?? []).map(s => ({
    name:  s.name,
    value: s.value
  })),
  actuators: filteredActuators
};

return [{ json: output }];
